-- Автономка: таблиця "віртуальних" товарів у Supabase.
-- Виконати ОДИН РАЗ у Supabase Dashboard -> SQL Editor -> New query -> Run.
-- (Безпечно виконати повторно навіть якщо стару версію без price/slug вже
-- застосовували - тут ALTER TABLE ADD COLUMN IF NOT EXISTS і ON CONFLICT DO
-- UPDATE, нічого не зламає й не задублює.)
--
-- Це НЕ реальні товари в наявності на нашому складі - вони існують, щоб
-- ловити пошуковий трафік за моделями постачальника, яких нема в реальному
-- фіді products.json. Ціна - реальна, з прайсу постачальника
-- (/home/tetiana/Downloads/price.xlsx), тож замовлення з такої картки
-- реально можна виконати, підвізши товар від постачальника під замовлення.
-- Кожен id і title мають префікс "V" (видимий і відвідувачам сайту), щоб
-- адмін одразу бачив у Supabase/аналітиці, що товар не з основного фіда.
--
-- Джерело: /home/tetiana/Downloads/prd_avto.xlsx (256 рядків), з яких
-- 46 співпали за id і 1 за назвою з реальними товарами products.json -
-- ці виключені. Лишилось 209 записів нижче. product_type - точний рядок
-- з SLUG_TO_CATEGORY в catalog.js/generate_static_pages.js (включно з
-- "Гибридні" - так написано в самому коді сайту), щоб товар потрапив у
-- ту саму категорію/фільтри, що й реальні товари.

create table if not exists public.virtual_products (
  id            text primary key,   -- "V" + model постачальника, напр. V142724
  source_model  text        not null,   -- оригінальний model-код постачальника без V (довідково, = mpn на сторінці товару)
  title         text        not null,   -- вже з префіксом "V " в назві, показується відвідувачам як є
  category      text        not null,   -- slug категорії: hybridni-invertory / akumulyatory / komplekty / kabeli / dzherela-zhyvlennya
  product_type  text,               -- людський опис категорії, ТОЧНО як в SLUG_TO_CATEGORY на сайті
  description   text,
  image         text,               -- відносний шлях assets/images/virtual/<id>.jpg (наш домен, фото перезалиті)
  price         numeric,            -- з прайсу постачальника (UAH)
  slug          text        not null,   -- для URL /product/<slug>/<id>.html, той самий slugify() підхід, що й у реальних товарів
  created_at    timestamptz not null default now()
);

alter table public.virtual_products add column if not exists price numeric;
alter table public.virtual_products add column if not exists slug text;

alter table public.virtual_products enable row level security;

drop policy if exists "anon can read virtual_products" on public.virtual_products;
create policy "anon can read virtual_products"
  on public.virtual_products for select
  to anon
  using (true);

drop policy if exists "authenticated can insert virtual_products" on public.virtual_products;
create policy "authenticated can insert virtual_products"
  on public.virtual_products for insert
  to authenticated
  with check (true);

drop policy if exists "authenticated can update virtual_products" on public.virtual_products;
create policy "authenticated can update virtual_products"
  on public.virtual_products for update
  to authenticated
  using (true)
  with check (true);

drop policy if exists "authenticated can delete virtual_products" on public.virtual_products;
create policy "authenticated can delete virtual_products"
  on public.virtual_products for delete
  to authenticated
  using (true);

on conflict (id) do update set
  source_model = excluded.source_model,
  title        = excluded.title,
  category     = excluded.category,
  product_type = excluded.product_type,
  description  = excluded.description,
  image        = excluded.image,
  price        = excluded.price,
  slug         = excluded.slug;
